* @deprecated (flag:FEATURE_NEXT_22222) method will be removed. Use getSomewhat instead
* @return int|string
*/
public  function getSomething()
{
if (Feature::isActive('FEATURE_NEXT_11111')) {
return 1;
} else {
return '1';
}
}
}

