_tmpTeleconsultPhoneNumber = _cursor.getString(_cursorIndexOfTeleconsultPhoneNumber);
final User.Capabilities _tmpCapabilities;
if (! (_cursor.isNull(_cursorIndexOfCanTeleconsult))) {
